/** Photos drawn for whole headings, at /problems/<vertical>/headings/<code>.webp. */
const HEADINGS = {
  laptop: new Set([
    'display', 'battery_power', 'charging', 'keyboard_touchpad', 'body_hinge', 'audio', 'camera', 'storage', 'performance',
    'software', 'connectivity', 'overheating', 'advanced_hardware', 'liquid_damage', 'data_recovery', 'upgrade', 'maintenance',
  ]),
  water_tank_care: new Set(['wt_cleaning', 'wt_inspection', 'wt_flushing', 'wt_repair', 'wt_addons']),
  two_wheeler: new Set([
    'tw_battery_electrical', 'tw_brakes', 'tw_chain_drive', 'tw_clutch_gear', 'tw_cooling', 'tw_engine',
    'tw_ev_battery', 'tw_ev_charging', 'tw_ev_controller', 'tw_ev_dashboard', 'tw_ev_motor', 'tw_maintenance',
    'tw_roadside', 'tw_starting', 'tw_tyres_wheels',
  ]),
  four_wheeler: new Set([
    'fw_battery_electrical', 'fw_body', 'fw_clutch', 'fw_cng', 'fw_cooling', 'fw_diagnostics',
    'fw_doors_locks', 'fw_engine', 'fw_ev_battery', 'fw_ev_charging', 'fw_ev_motor', 'fw_exhaust',
    'fw_fuel', 'fw_glass', 'fw_infotainment', 'fw_interior', 'fw_lights', 'fw_maintenance',
    'fw_roadside', 'fw_safety', 'fw_starting', 'fw_steering', 'fw_transmission', 'fw_tyres_wheels',
  ]),
};

/** The photo that stands for a whole heading (Display, Camera…). */
const COVERS = {
  mobile: {
    display: 'cracked_screen',
    battery_power: 'battery_swelling',
    charging: 'charging_port_damaged',
    audio: 'speaker_not_working',
    camera: 'camera_glass_broken',
    physical: 'back_glass_broken',
    connectivity: 'network_signal_problem',
    software: 'phone_slow',
  },
};

/** Service codes and booking-flow names that mean the same vertical. */
const VERTICAL = {
  mobile: 'mobile', mobile_repair: 'mobile', laptop: 'laptop', laptop_repair: 'laptop',
  two_wheeler: 'two_wheeler', four_wheeler: 'four_wheeler',
  water_tank_care: 'water_tank_care',
};

const url = (v, code) => (PHOTOS[v]?.has(code) ? `/problems/${v}/${code}.webp` : null);

/** A problem's picture: its own upload, else ours, else null. */
export function problemPhoto(vertical, problem) {
  if (problem?.imageUrl) return problem.imageUrl;
  return url(VERTICAL[vertical], problem?.code);
}

/**
 * Verticals whose problems borrow their heading's photo when they have none of
 * their own, so every issue inside a heading is a picture card.
 */
const HEADING_FALLBACK = new Set(['laptop', 'two_wheeler', 'four_wheeler', 'water_tank_care']);

/** A problem's picture inside a heading: its own, else the heading's where that vertical allows it. */
export function problemPhotoIn(vertical, problem, category) {
  const own = problemPhoto(vertical, problem);
  if (own || !category || !HEADING_FALLBACK.has(VERTICAL[vertical])) return own;
  return categoryPhoto(vertical, category);
}

/** A heading's picture: its own upload, its cover, else any of its problems'. */
export function categoryPhoto(vertical, category) {
  if (category?.imageUrl) return category.imageUrl;
  const v = VERTICAL[vertical];
  if (!v) return null;
  if (HEADINGS[v]?.has(category?.code)) return `/problems/${v}/headings/${category.code}.webp`;
  const cover = url(v, COVERS[v]?.[category?.code]);
  if (cover) return cover;
  for (const p of category?.problems || []) {
    const u = url(v, p.code);
    if (u) return u;
  }
  return null;
}

/**
 * The photo that stands for a whole service (a tile on "All services" and the
 * home grid), when admin has not uploaded one. Only services we have a real
 * photo for are listed; the rest keep their illustration or icon.
 */
const SERVICE_COVERS = {
  mobile: '/problems/mobile/cracked_screen.webp',
  laptop: '/problems/laptop/headings/display.webp',
  two_wheeler: '/problems/two_wheeler/headings/tw_engine.webp',
  four_wheeler: '/problems/four_wheeler/headings/fw_engine.webp',
  water_tank_care: '/problems/water_tank_care/headings/wt_cleaning.webp',
};
/** Helping: each errand type has its own photo; the two service lines use their main one. */
const HELPING = {
  shopping: 'shopping', pickup: 'pickup', return: 'return', exchange: 'exchange',
  shopping_pickup: 'shopping', returns_exchange: 'return', helping_services: 'shopping', helping: 'shopping',
};
const PET_SERVICES = new Set(['pet_boarding', 'pet_check', 'pet_grooming', 'pet_home_care', 'pet_transport', 'pet_vet_assist', 'pet_walk']);

// Photo tiles for home and section grids (assets/web/services/tiles, 320 px WebP).
const TILES = new Set(['bike_wash', 'car_wash', 'water_tank_care', 'shopping_pickup', 'fa_grocery_run', 'fa_doctor_escort', 'fa_elder_checkin', 'fa_party_helper', 'fa_puja_help']);

export function servicePhoto(code) {
  if (TILES.has(code)) return `/services/tiles/${code}.webp`;
  if (PET_SERVICES.has(code)) return `/services/pet/${code}.webp`;
  if (code === 'pet_services') return '/services/pet/pet_grooming.webp';
  if (HELPING[code]) return `/services/helping/${HELPING[code]}.webp`;
  return SERVICE_COVERS[VERTICAL[code]] || null;
}
